{
  "name": "可寻址行记录存储组件",
  "name_en": "Seekable Line-Record Storage Component",
  "manufacturer": "",
  "description": "一种非物理的软件文件存储组件，用于读写以换行分隔的记录，并维护行索引以实现按行快速定位。适合在实验过程中保存日志、样本记录、目录清单和相关元数据。",
  "description_en": "A non-physical software file storage component for reading and writing newline-delimited records while maintaining a line index for fast random access by line. It is useful in experiments for storing logs, sample records, catalogs, manifests, and related metadata.",
  "actions": [
    {
      "action_name": "auto-writeline",
      "description": "写入一条以换行分隔的记录。",
      "description_en": "Write one newline-delimited record."
    },
    {
      "action_name": "auto-readline",
      "description": "读取当前位置的一行记录。",
      "description_en": "Read one record from the current position."
    },
    {
      "action_name": "auto-seek_line_start",
      "description": "将读写位置移动到指定行的起始处。",
      "description_en": "Move the read/write position to the start of the specified line."
    },
    {
      "action_name": "auto-seek_end_of_file",
      "description": "将读写位置移动到文件末尾。",
      "description_en": "Move the read/write position to the end of the file."
    },
    {
      "action_name": "auto-truncate_until_end",
      "description": "从指定行开始截断到文件末尾。",
      "description_en": "Truncate the file from the specified line to the end."
    },
    {
      "action_name": "auto-read_from",
      "description": "从指定行开始读取后续记录。",
      "description_en": "Read records starting from the specified line."
    },
    {
      "action_name": "auto-update_line",
      "description": "更新指定行的记录内容。",
      "description_en": "Update the contents of the specified line."
    },
    {
      "action_name": "auto-lines",
      "description": "获取已索引的行数。",
      "description_en": "Get the number of indexed lines."
    },
    {
      "action_name": "auto-has_content",
      "description": "检查文件是否包含内容。",
      "description_en": "Check whether the file contains any content."
    },
    {
      "action_name": "auto-close",
      "description": "关闭底层文件资源。",
      "description_en": "Close the underlying file resource."
    }
  ],
  "tag_hints": [
    "newline-delimited records",
    "seekable file IO",
    "random access by line",
    "catalog and manifest storage",
    "experiment data logging",
    "memory-mapped file support"
  ]
}

